#!/usr/bin/env bash
# Mock agent binary for TokenForGood CI E2E tests.
# Simulates Claude Code tool calls inside the sandbox container.
# Exit code 0 = success, 1 = simulated failure.

set -euo pipefail

WORKSPACE="/workspace"
LOG_DIR="/workspace/.tokenforgood"
BROKER_URL="${BROKER_URL:-http://host.docker.internal:8080}"
BROKER_NONCE="${BROKER_NONCE:-}"

echo "[mock-agent] Starting mock agent in ${WORKSPACE}"
echo "[mock-agent] Broker URL: ${BROKER_URL}"

# --- Simulate reading files in /workspace ---
echo "[mock-agent] Reading workspace files..."
ls -la "${WORKSPACE}" 2>/dev/null || echo "[mock-agent] Workspace is empty (expected on first run)"

# --- Simulate writing files in /workspace ---
echo "[mock-agent] Writing test file..."
echo "// Generated by mock agent" > "${WORKSPACE}/test-output.js"

# --- Attempt to read sensitive paths (should fail in sandbox) ---
echo "[mock-agent] Testing sandbox isolation..."

if cat /root/.ssh/id_rsa 2>/dev/null; then
  echo "[mock-agent] SECURITY FAILURE: read /root/.ssh/id_rsa"
  exit 1
else
  echo "[mock-agent] OK: cannot read /root/.ssh/ (expected)"
fi

if cat /etc/shadow 2>/dev/null; then
  echo "[mock-agent] SECURITY FAILURE: read /etc/shadow"
  exit 1
else
  echo "[mock-agent] OK: cannot read /etc/shadow (expected)"
fi

# --- Attempt non-allowlisted network access (should be blocked by proxy) ---
echo "[mock-agent] Testing network isolation..."

if curl -s --max-time 5 https://evil.example.com 2>/dev/null; then
  echo "[mock-agent] SECURITY FAILURE: reached non-allowlisted domain"
  exit 1
else
  echo "[mock-agent] OK: non-allowlisted domain blocked (expected)"
fi

# --- Call credential broker with valid nonce ---
echo "[mock-agent] Testing credential broker (valid nonce)..."

CLONE_RESPONSE=$(curl -s -w "\n%{http_code}" \
  -X POST \
  -H "Content-Type: application/json" \
  -H "X-Broker-Nonce: ${BROKER_NONCE}" \
  -d "{\"repo\": \"${TFG_REPO:-owner/repo}\"}" \
  "${BROKER_URL}/clone-repo" 2>/dev/null || echo "000")

CLONE_STATUS=$(echo "${CLONE_RESPONSE}" | tail -1)
echo "[mock-agent] Clone response status: ${CLONE_STATUS}"

# --- Call credential broker with invalid nonce (should get 403) ---
echo "[mock-agent] Testing credential broker (invalid nonce)..."

INVALID_RESPONSE=$(curl -s -w "\n%{http_code}" \
  -X POST \
  -H "Content-Type: application/json" \
  -H "X-Broker-Nonce: invalid-nonce-should-fail" \
  -d "{\"repo\": \"owner/repo\"}" \
  "${BROKER_URL}/clone-repo" 2>/dev/null || echo "000")

INVALID_STATUS=$(echo "${INVALID_RESPONSE}" | tail -1)
if [ "${INVALID_STATUS}" = "403" ]; then
  echo "[mock-agent] OK: invalid nonce correctly rejected (403)"
else
  echo "[mock-agent] WARNING: expected 403 for invalid nonce, got ${INVALID_STATUS}"
fi

# --- Generate stdout for logging ---
echo "[mock-agent] Generating stdout for execution log..."
for i in $(seq 1 5); do
  echo "[mock-agent] Tool call ${i}: edit file test-output.js"
done

echo "[mock-agent] Mock agent completed successfully"
exit 0
